def pons_fleischmann_excess_heat(PdD_loading=0.9, volume=1e-6):
    """Pons-Fleischmann low-radiation excess heat via SCm buoyancy coupling (1-10 W range)"""
    rho_Pd = 6.8e28              # Pd atomic density [atoms/m^3]
