class _CP4Calculator:
    """Base class for all CP4 stateless calculators."""

    category: str = "Miscellaneous"

    def compute(self, dataset: dict = None) -> dict:
        return {}

    def dpm_ug1_seed(self, M=1.989e30, r=6.96e8, B=1e-4):
        """Delegate to module-level dpm_ug1_seed."""
        return dpm_ug1_seed(M, r, B)

    def dpm_ug1_seed(self, M=1.989e30, r=6.96e8, B=1e-4):
        """Backward-compat alias for dpm_ug1_seed."""
        return dpm_ug1_seed(M, r, B)

    @classmethod
    def __init_subclass__(cls, **kwargs):
        """Auto-wrap subclass compute() to guard overflow/zerodiv/type errors."""
        super().__init_subclass__(**kwargs)
        if 'compute' in cls.__dict__:
            _orig = cls.__dict__['compute']
            def _safe(self_obj, *_a, **_kw):
                try:
                    return _orig(self_obj, *_a, **_kw)
                except (OverflowError, ZeroDivisionError, FloatingPointError,
                        TypeError, ValueError, AttributeError) as _e:
                    return {
                        'result': 0.0,
                        'error': repr(_e)[:200],
                        'guarded': True,
                        'paper': getattr(self_obj, 'PAPER', 'unknown'),
                    }
            cls.compute = _safe

    @staticmethod
    def _e_react(t: float, kappa: float = KAPPA) -> float:
        """E_react = 1e46 * exp(-kappa * t)  (t in days)."""
        return E_REACT_BASE * math.exp(-kappa * t)

    @staticmethod
    def _cos_tn(t_n: float) -> float:
        """cos(p t_n) � oscillatory reversal term."""
        return math.cos(math.pi * t_n)

    @staticmethod
    def _ssq_exp(n: int) -> float:
        """exp(-[SSq] * n/26) � Ramanujan suppression factor."""
        return math.exp(-SSQ * n / 26.0)


