        k_rel_0 = dataset.get("k_rel_0", 1.0e-3)
        t       = dataset.get("t", 0.0)
        t_n     = dataset.get("t_n", 0.0)
        alpha   = dataset.get("alpha", ALPHA_DECAY)
        nu_THz  = dataset.get("nu_THz", 1.0e12)
        f_UA    = dataset.get("f_UA", 0.999)
        f_SCm   = dataset.get("f_SCm", 0.001)
