        fTRZ       = float(dataset.get('fTRZ',       0.1))
        c          = self._C

        # System parameters
        Vsys   = float(dataset.get('Vsys',   4.189e12))   # m�
        vexp   = float(dataset.get('vexp',   1e3))         # m/s
        ffluid = float(dataset.get('ffluid', 1.269e-14))  # Hz
        Ereact = float(dataset.get('Ereact', 1.0))
