    OMEGA_G   = 7.3e-16
    MBH       = 8.155e36
    DG        = 2.62e20
    EPSILON_SW = 1e-3
    RHO_SW    = 8e-21    # solar wind density at 1 AU kg/m�
    U_UA      = 1.0

    def compute(self, dataset: dict) -> dict:
        import math

        beta_i     = dataset.get('beta_i', self.BETA_I)
        Omega_g    = dataset.get('Omega_g', self.OMEGA_G)
        Mbh        = dataset.get('Mbh', self.MBH)
