        # Group E � Extended / Cosmological (Docs 21�29)
        ('NGC7469_AGN',         2.8e23,  5.5e43,   'AGN_SF',        {'M_BH': 1e39, 'r_BH': 1e13, 'M_sf': 0.05}),
        ('M87_Jet',             1.55e25, 6.5e42,   'GW_spindown',   {'dOmega_dt': 1e-12}),
