_PHI       = (1.0 + math.sqrt(5.0)) / 2.0  # F = 1.61803�  (DVP golden ratio)
_P_THRESH  = 0.18            # min P_order for stable nucleus (from Grok)
_RHO_NUC   = 2.3e17          # kg/m�  nuclear density
