    def _omega_lqg(self, k_wave: float, eta: float = 1.0, gamma: float = 1.0) -> float:
        """?_LQG = c�k�v(1 + ?(l_Pl�k)^?)"""
        corr = 1.0 + eta * (self._L_PL * k_wave) ** gamma
