# CP4 #253 ? UQFFComparedToGW150914Calculator
# PAPER_669 | Session 172 | April 2, 2026
# ==========================================================================

class UQFFComparedToGW150914Calculator:
    """
    CP4 Calculator #253 | PAPER_669
    UQFF vs LIGO GW150914 � Chirp mass Mc=(m1*m2)^3/5/(m1+m2)^1/5. h_UQFF=h_GR*(1-f_TRZ)*S_SCm*exp(-U_m*omega/c^2). Phase shift: dphi_UQFF=dphi_GR+kappa*f_TRZ*t. GW150914: m1=36, m2=29 Msun, d=410 Mpc, f_peak=150 Hz.
    """
    ENTRY = 253
    PAPER = "PAPER_669"
    CPP_MODULE = "UQFFComparedToGW150914"
    UQFF_CONSTANTS = {
        "rho_UA": _RHO_VAC_UA, "rho_SCm": _RHO_VAC_SCM, "f_TRZ": 0.1,
        "kappa": 0.0005, "SSq": 0.57, "mu_j": 3.38e23, "gamma": 5e-5,
    }
    PARAMETERS = {
        "m1_kg": {"type": "float", "default": 7.16e+31, "desc": "Primary mass in kg"},
        "m2_kg": {"type": "float", "default": 5.77e+31, "desc": "Secondary mass in kg"},
        "d_m": {"type": "float", "default": 1.27e+25, "desc": "Luminosity distance in m"},
        "f_Hz": {"type": "float", "default": 150.0, "desc": "GW frequency in Hz"},
    }
    PRIMARY_OUTPUT = "h_UQFF"
    EQUATIONS = [
        "Mc = (m1*m2)^(3/5) / (m1+m2)^(1/5)  [chirp mass]",
        "h_GR(f) = (4/d)*(G*Mc/c^2)^(5/3)*(pi*f/c)^(2/3)  [leading-order strain]",
        "S_SCm(f) = exp(-rho_SCm*c/f)  [SCm wavelength damping]",
        "h_UQFF = h_GR*(1-f_TRZ)*S_SCm*exp(-U_m*omega/c^2)",
        "phi_UQFF(t) = 2*pi*f*t + kappa*f_TRZ*t  [UQFF phase shift]",
        "df/dt = (96/5)*pi^(8/3)*(G*Mc)^(5/3)/c^5 * f^(11/3)  [chirp rate]",
    ]

    def compute(self, params: dict = None) -> dict:
        if params is None:
            params = {k: v["default"] for k, v in self.PARAMETERS.items()}
        import math
        G    = 6.6743e-11;  C    = 2.998e8
        HBAR = 1.0546e-34;  K_B  = 1.380649e-23
        PI   = math.pi
        RHO_SCM  = _RHO_VAC_SCM;  F_TRZ = 0.1
        MU_J     = 3.38e23;   GAMMA = 5.0e-5 / 86400.0
        T_N_REF  = 1.0e8;     KAPPA = 0.0005
        M_SUN    = 1.989e30

        m1 = float(params.get("m1_kg", 7.16e31))
        m2 = float(params.get("m2_kg", 5.77e31))
        d  = float(params.get("d_m",   1.27e25))   # 410 Mpc
        f  = float(params.get("f_Hz",  150.0))

        # Chirp mass (PAPER_669 �2)
        Mc = (m1 * m2)**0.6 / (m1 + m2)**0.2

        # Standard GR strain (PAPER_669 �3)
        h_GR = (4.0 / d) * (G * Mc / C**2)**(5.0/3.0) * (PI * f / C)**(2.0/3.0)

        # SCm wavelength damping (PAPER_669 �4)
        lambda_GW = C / max(f, 1e-300)
        S_SCm = math.exp(-min(RHO_SCM * lambda_GW, 700.0))

        # Schwarzschild radius and U_m for string impedance
        M_total = m1 + m2
        r_s = 2.0 * G * M_total / (C * C)
        Um = (MU_J / max(r_s, 1e-10)) * (1.0 - math.exp(-GAMMA * T_N_REF * math.cos(PI)))
        Um = max(Um, 0.0)
        omega = 2.0 * PI * f

        # UQFF-modified strain (PAPER_669 �4)
        h_UQFF = h_GR * (1.0 - F_TRZ) * S_SCm * math.exp(-min(Um * omega / C**2, 700.0))

        # Phase shift (PAPER_669 �5)
        t_obs = 1.0  # 1 second reference
        phi_GR   = 2.0 * PI * f * t_obs
        phi_UQFF = phi_GR + KAPPA * F_TRZ * t_obs
        delta_phi = KAPPA * F_TRZ * t_obs

        # Chirp rate (PAPER_669 �6)
        df_dt = (96.0 / 5.0) * PI**(8.0/3.0) * (G * Mc)**(5.0/3.0) / C**5 * f**(11.0/3.0)

        # Chirp mass in solar masses
        Mc_Msun = Mc / M_SUN

        return {
            "entry":           253,
            "paper":           "PAPER_669",
            "class":           "UQFFComparedToGW150914Calculator",
            "m1_kg":           m1,
            "m2_kg":           m2,
            "d_m":             d,
            "f_Hz":            f,
            "Mc_kg":           Mc,
            "Mc_Msun":         Mc_Msun,
            "h_GR":            h_GR,
            "S_SCm":           S_SCm,
            "h_UQFF":          h_UQFF,
            "h_ratio":         h_UQFF / max(abs(h_GR), 1e-300),
            "suppression_pct": (1.0 - h_UQFF / max(abs(h_GR), 1e-300)) * 100.0,
            "phi_GR_rad":      phi_GR,
            "phi_UQFF_rad":    phi_UQFF,
            "delta_phi_rad":   delta_phi,
            "df_dt_Hzs":       df_dt,
            "Um_J":            Um,
            "equations": [
                "Mc = (m1*m2)^(3/5)/(m1+m2)^(1/5)",
                "h_GR = (4/d)*(G*Mc/c^2)^(5/3)*(pi*f/c)^(2/3)",
                "S_SCm = exp(-rho_SCm*c/f)",
                "h_UQFF = h_GR*(1-f_TRZ)*S_SCm*exp(-U_m*omega/c^2)",
                "phi_UQFF = 2*pi*f*t + kappa*f_TRZ*t",
                "df/dt = (96/5)*pi^(8/3)*(G*Mc)^(5/3)/c^5*f^(11/3)",
            ],
        }

    def simulate(self, f_array, **kwargs):
        return [self.compute({"f_Hz": f}) for f in f_array]

    def add_mod(self, fn):
        pass  # Extensible; attach via subclass

    def update_from_file(self, filepath: str):
        import json, os
        if not os.path.isfile(filepath): return
        with open(filepath, "r") as f:
            try: data = json.load(f)
            except: return




