    def compute(self, params=None):
        import math
        p = {k: v for _, k, v, _ in self.PARAMETERS}
        if params:
            p.update(params)
        G, c = 6.674e-11, 3e8
        H0 = 2.184e-18
        M  = p.get("M_kg", 2.785e30)
        r  = p.get("r_m", 2.0e4)
        B0 = p.get("B0_T", 1e10)
        tau_B = p.get("tau_B_s", 1.262e11)
        B_crit = p.get("B_crit_T", 1e11)
