        # Gravitational radius
        r_g = c["G"] * M_BH / c["c"]**2

        # Acceleration timescale
        tau_acc = 1.0 / (2 * c["K_diff"])

        # CRP injection rate (proportional to magnetic fluctuation)
        eta_eff = c["eta_inj"] * max(1.0, c["beta_mag"])
        N_dot_inj = eta_eff * Mdot_frac * c["c"] / r_g

