        s26 = sum(math.exp(-self.SSQ * k / 26.0) for k in range(1, 27))
        Phi_ph = self.PHI_0 * s26
        energy_ratio = E_net / E_GW if E_GW > 0 else 0.0

        D_phonon = (2.0 / 3.0) * Phi_ph * energy_ratio
        h_UQFF = h_GR * (1 - D_phonon)
