    PARAMETERS = {"M_Msun": 5.5e7, "a_spin": 0.70, "B_T": 3000, "A_jet": 0.95}

    def compute(self, dataset: dict) -> dict:
        M = float(dataset.get("M_Msun", 5.5e7)) * 1.989e30
