        Msun = 1.989e30; G0 = 6.674e-11; C0 = 2.998e8
        total_Ug, total_Ub = 0.0, 0.0
        for i in range(99):
            if i < 20: M=(0.1+i*5)*Msun; r=1e9*(1+i*0.5)
            elif i < 40: M=(1e9+(i-20)*5e11)*Msun; r=1e20*(1+(i-20)*0.3)
