# -- CP4 #592 -- PAPER_1151 -- Group A: BH26*BSH Resonance -------------------
class BH26BSHResonanceCalculator_S234(_CP4Calculator):
    """BH26 spectral ladder cross-resonance with BSH (Buoyancy Harmonic Series).
    BSH evaluated at f_k=f_RR/lambda_k; energy_density_k=resonance_k*rho_SCm.
    PAPER_1151, Session 202 T75-T80.
    """
    category = "VDS/DVP/BH26"
    def compute(self, dataset: dict = None) -> dict:
        import math
        d = dataset or {}
        N = d.get('N', 10)
        f_RR = d.get('f_RR', 1.15e14)
        t_n = d.get('t_n', 0.0)
        rho = float(_SCM_RHO_VAC)
        lambdas = [k*(k+25) for k in range(1, N+1)]
        freqs = [f_RR / lk for lk in lambdas]
        cos_tn = self._cos_tn(t_n)
        H = lambda m: sum(1/k for k in range(1, m+1))
        bsh_max = sum(H(m) for m in range(1, 27))
        resonances = []
        energy_densities = []
        for fi in freqs:
            x = fi / f_RR
            bsh_val = sum(H(m) * (1 - math.exp(-x * m)) for m in range(1, 27))
            res_k = (bsh_val / bsh_max) * cos_tn
            e_k = res_k * rho
            resonances.append(round(res_k, 8))
            energy_densities.append(e_k)
        return {
            'primary_equations': [
                f"f_k = f_RR / lambda_k for k=1..{N}",
                f"BSH(x) = sum_{{m=1}}^26 H_m * (1-exp(-x*m))",
                f"resonance_k = (BSH(f_k/f_RR)/BSH_max) * cos(pi*t_n)",
                f"energy_density_k = resonance_k * rho_SCm  [J/m^3]",
                f"BSH_max = sum H_m = {bsh_max:.4f}",
            ],
            'available_equations': [
                "H_m = sum_{k=1}^m 1/k  (m-th harmonic number)",
                "BSH fixed-point: BSH(x)/BSH_max = x -> solve for x = [SSq]",
                "energy_density = resonance * rho_SCm  [J/m^3]",
            ],
            'simulation_set': [
                {'quantity': 'resonances', 'value': resonances[:5]},
                {'quantity': 'energy_densities', 'value': energy_densities[:5]},
                {'quantity': 'bsh_max', 'value': bsh_max},
                {'quantity': 'n_bins', 'value': N},
            ],
            'source': 'PAPER_1151 Session 202 T75-T80',
        }


# -- CP4 #593 -- PAPER_1154/1155 -- Group B: DPM Quantum Chain ---------------
class DPMQuantumChainCalculator_S234(_CP4Calculator):
    """DPM quantum chain: 26-layer weights w_i=i^6=[SCm]_i*[UA]_i*B0_i=i^2*i*i^3.
    A_26=sum(i^6,i=1..26)=1,307,797,101 exact. AMU_DPM=rho_SCm/SSq*A_26.
    PAPER_1154/PAPER_1155, Session 202.
    """
    category = "DPM/Quantum-Chain"
    def compute(self, dataset: dict = None) -> dict:
        d = dataset or {}
        rho = d.get('rho_SCm', float(_SCM_RHO_VAC))
        ssq = d.get('SSq', float(_SCM_SSQ))
        A_26 = sum(i**6 for i in range(1, 27))
        M0_dpm = rho / ssq
        AMU_derived = M0_dpm * A_26
        AMU_obs = 1.661e-27
        error_pct = (AMU_derived - AMU_obs) / AMU_obs * 100
        layers = [{'i': i, 'i6': i**6, 'SCm_i': i**2, 'UA_i': i, 'B0_i': i**3}
                  for i in range(1, 27)]
        return {
            'primary_equations': [
                f"w_i = [SCm]_i * [UA]_i * B0_i = i^2 * i * i^3 = i^6",
                f"A_26 = sum(i^6, i=1..26) = {A_26}  (exact integer)",
                f"M0_DPM = rho_SCm / [SSq] = {M0_dpm:.4e} kg",
                f"AMU_DPM = M0_DPM * A_26 = {AMU_derived:.4e} kg",
                f"AMU_obs = {AMU_obs:.4e} kg  -->  error = {error_pct:.2f}%",
            ],
            'available_equations': [
                "[SCm]_i = i^2  (triadic quantum state)",
                "[UA]_i = i     (UA ladder, index.js UA_i=i)",
                "B0_i = i^3    (magnetic dipole at r_i=R_nuc/i => B~1/r^3)",
                "sum(i^6, 1..N) = N(N+1)(2N+1)(3N^4+6N^3-3N+1)/42",
            ],
            'simulation_set': [
                {'quantity': 'A_26', 'value': A_26},
                {'quantity': 'AMU_derived_kg', 'value': AMU_derived},
                {'quantity': 'error_pct', 'value': error_pct},
                {'quantity': 'layer_26', 'value': layers[-1]},
            ],
            'source': 'PAPER_1154/PAPER_1155 Session 202',
        }


# -- CP4 #594 -- PAPER_1154 -- Group B: [SSq] First-Principles ---------------
class SSqFirstPrinciplesCalculator_S234(_CP4Calculator):
    """[SSq]=0.57 first-principles: Method A DPM geometry (v_SCm=c/3, error +0.34%).
    gamma=3/(2sqrt(2)); [SSq]_A = rho_ratio * (1 - 1/gamma) = 10*(1-2sqrt2/3).
    Also Method B (Riemann VDS) and Bootstrap (AMU constraint).
    PAPER_1154, Session 202 commit 0e7a2ebf.
    """
    category = "DPM/Quantum-Chain"
    def compute(self, dataset: dict = None) -> dict:
        import math
        d = dataset or {}
        c = 2.998e8
        v_scm = c / 3.0
        gamma = 1.0 / math.sqrt(1 - (v_scm/c)**2)
        inv_gamma = 1.0 / gamma
        dpm_ratio = d.get('dpm_ratio', 10.0)
        SSq_A = dpm_ratio * (1 - inv_gamma)
        SSq_canonical = 0.57
        error_A = (SSq_A - SSq_canonical) / SSq_canonical * 100
        SSq_B = 0.507
        error_B = (SSq_B - SSq_canonical) / SSq_canonical * 100
        A_26 = sum(i**6 for i in range(1, 27))
        rho = float(_SCM_RHO_VAC)
        AMU_obs = 1.661e-27
        SSq_boot = rho * A_26 / AMU_obs
        error_boot = (SSq_boot - SSq_canonical) / SSq_canonical * 100
        return {
            'primary_equations': [
                f"Method A: v_SCm=c/3; gamma=3/(2*sqrt2)={gamma:.5f}",
                f"  [SSq]_A = 10*(1-2*sqrt2/3) = {SSq_A:.6f}  (error {error_A:+.2f}%)",
                f"Method B: Z=Li_26(SSq)~SSq~0.507 (Riemann critical line 1/2+delta)",
                f"  [SSq]_B = {SSq_B:.4f}  (error {error_B:+.1f}%)",
                f"Bootstrap: rho_SCm*A_26/AMU = {SSq_boot:.6f}  (error {error_boot:+.2f}%)",
                f"Canonical: [SSq] = {SSq_canonical}",
            ],
            'available_equations': [
                "[SSq]_A = (rho_UA/rho_SCm) * (1 - 1/gamma_SCm)",
                "gamma_SCm = 1/sqrt(1 - v_SCm^2/c^2), v_SCm = c/3",
                "[SSq]_B: Li_26(z)~z at z=0.507, Riemann Re(s)=1/2",
                "[SSq]_boot = rho_SCm * A_26 / AMU_obs",
            ],
            'simulation_set': [
                {'quantity': 'SSq_A', 'value': SSq_A},
                {'quantity': 'SSq_B', 'value': SSq_B},
                {'quantity': 'SSq_boot', 'value': SSq_boot},
                {'quantity': 'SSq_canonical', 'value': SSq_canonical},
                {'quantity': 'error_A_pct', 'value': error_A},
            ],
            'source': 'PAPER_1154 Session 202 commit 0e7a2ebf',
        }


# -- CP4 #595 -- PAPER_1152 -- Group E: Source7 VDS Bridge -------------------
class Source7VDSBridgeCalculator_S234(_CP4Calculator):
    """Source7 VDS bridge: passes VDSBranchResult through sim-engine Stage 2.
    Validates vds_prime~1.0 fixed-point. PAPER_1151/PAPER_1152, Session 202-203.
    """
    category = "VDS/DVP/BH26"
    def compute(self, dataset: dict = None) -> dict:
        d = dataset or {}
        z = d.get('SSq', float(_SCM_SSQ))
        n_max = d.get('n_max', 200)
        li26 = sum(z**n / n**26 for n in range(1, n_max + 1))
        li25 = sum(z**n / n**25 for n in range(1, n_max + 1))
        vds_prime = li25 / z if z != 0 else 0.0
        vds_density = li26 * float(_SCM_RHO_VAC)
        vds_k_weighted = li25 + 25 * li26
        fixed_point_ok = abs(vds_prime - 1.0) < 0.1
        return {
            'primary_equations': [
                "[Source7 VDS Bridge Stage 2]",
                f"Li_26({z:.4f}) = {li26:.8f}",
                f"vds_prime = {vds_prime:.8f}  (fixed-point ok: {fixed_point_ok})",
                f"vds_k_weighted = {vds_k_weighted:.8f}",
            ],
            'available_equations': [
                "Stage 2 output feeds Stage 8 BSFG via vds_k_weighted",
                "Fixed-point test: |vds_prime - 1| < 0.1 at SSq=0.57",
            ],
            'simulation_set': [
                {'quantity': 'vds_prime', 'value': vds_prime},
                {'quantity': 'vds_density', 'value': vds_density},
                {'quantity': 'vds_k_weighted', 'value': vds_k_weighted},
                {'quantity': 'fixed_point_ok', 'value': fixed_point_ok},
            ],
            'source': 'PAPER_1151/1152 Session 202-203',
        }


# -- CP4 #596 -- PAPER_1152 -- Group E: Source7 DVP Bridge -------------------
class Source7DVPBridgeCalculator_S234(_CP4Calculator):
    """Source7 DVP bridge: passes DVPBranchResult through sim-engine Stage 3.
    Validates zeta_sum>0 and a(29)>0. PAPER_1151/PAPER_1152, Session 202-203.
    """
    category = "VDS/DVP/BH26"
    def compute(self, dataset: dict = None) -> dict:
        d = dataset or {}
        z = d.get('SSq', float(_SCM_SSQ))
        all_primes = [x for x in range(2, 201) if all(x % j != 0 for j in range(2, x))]
        primes_above_26 = [p for p in all_primes if p > 26]
        def pi_func(p): return sum(1 for q in all_primes if q <= p)
        zeta_dvp = sum(z**pi_func(p) / p**26 for p in primes_above_26)
        a29 = z**pi_func(29) / 29**26
        return {
            'primary_equations': [
                "[Source7 DVP Bridge Stage 3]",
                f"zeta_DVP({z:.4f}) = {zeta_dvp:.4e}",
                f"a(29) = {a29:.4e}",
                f"n_primes_above_26 = {len(primes_above_26)}",
            ],
            'available_equations': [
                "Stage 3 output feeds Stage 5 VDS*DVP coupled field",
                "Dominant term: p=29 (first prime > 26)",
            ],
            'simulation_set': [
                {'quantity': 'zeta_dvp', 'value': zeta_dvp},
                {'quantity': 'a29', 'value': a29},
                {'quantity': 'n_primes', 'value': len(primes_above_26)},
            ],
            'source': 'PAPER_1151/1152 Session 202-203',
        }


# -- CP4 #597 -- PAPER_1152 -- Group E: Source7 Triple-Point -----------------
class Source7TriplePointCalculator_S234(_CP4Calculator):
    """Source7 triple-point convergence: |g_C-g_R|/g_R<1%, |g_R-g_BSFG|/g_BSFG<1%.
    Determines SSq=0.57 uniquely as the simultaneous convergence point.
    PAPER_1152 Stage 9, Session 203.
    """
    category = "VDS/DVP/BH26"
    def compute(self, dataset: dict = None) -> dict:
        d = dataset or {}
        g_C = d.get('g_C', 1.0e-9)
        g_R = d.get('g_R', 1.0e-9)
        g_B = d.get('g_BSFG', 1.0e-9)
        tol = d.get('tolerance_pct', 1.0) / 100.0
        cr = abs(g_C - g_R) / abs(g_R) if g_R != 0 else float('inf')
        rb = abs(g_R - g_B) / abs(g_B) if g_B != 0 else float('inf')
        cb = abs(g_C - g_B) / abs(g_B) if g_B != 0 else float('inf')
        triple_ok = (cr < tol) and (rb < tol) and (cb < tol)
        return {
            'primary_equations': [
                f"|g_C - g_R| / g_R = {cr:.4f}  ({'PASS' if cr<tol else 'FAIL'})",
                f"|g_R - g_BSFG| / g_BSFG = {rb:.4f}  ({'PASS' if rb<tol else 'FAIL'})",
                f"|g_C - g_BSFG| / g_BSFG = {cb:.4f}  ({'PASS' if cb<tol else 'FAIL'})",
                f"Triple-point convergence: {'PASS' if triple_ok else 'FAIL'}",
            ],
            'available_equations': [
                "Triple-point at SSq=0.57 uniquely determined",
                "g_BSFG = a_DPM * joint_coeff * vds_k_weighted * Sigma/1760",
            ],
            'simulation_set': [
                {'quantity': 'cr_ratio', 'value': cr},
                {'quantity': 'rb_ratio', 'value': rb},
                {'quantity': 'cb_ratio', 'value': cb},
                {'quantity': 'triple_point_ok', 'value': triple_ok},
            ],
            'source': 'PAPER_1152 Stage 9 Session 203',
        }


