# -- CP4 #599 -- PAPER_1153 -- PTF Net-Zero Proof ----------------------------
class PrimordialTimingFunctionCalculator_S234(_CP4Calculator):
    """Primordial Timing Function (PTF): net-zero displacement D_A+D_B=+3+(-3)=0.
    int_0^1 cos(pi*t_n) dt_n = 0 (exact); f=F4=3, b=F3=2, n=floor(pi)=3.
    Pi-digit epoch clock; Epoch 5 [9,7,9] = reverse boundary (not predicted).
    PAPER_1153, Session 203 commit 2637b384.
    """
    category = "Primordial/PTF"
    def compute(self, dataset: dict = None) -> dict:
        import math
        d = dataset or {}
        f_fwd = 3; b_bck = 2; n_rep = 3
        D_A = f_fwd; D_B = -f_fwd; D_net = D_A + D_B
        integral = (math.sin(math.pi) - math.sin(0.0)) / math.pi
        fib_ratio = f_fwd / b_bck
        epochs = [
            {'digits': [3,1,4], 'label': 'Formation'},
            {'digits': [1,5,9], 'label': 'Expansion'},
            {'digits': [2,6,5], 'label': 'Stabilisation'},
            {'digits': [3,5,8], 'label': 'Acceleration'},
            {'digits': [9,7,9], 'label': 'REVERSE BOUNDARY (not predicted)'},
        ]
        cpt_ok = abs(D_net) == 0 and abs(integral) < 1e-10
        return {
            'primary_equations': [
                f"f=F4={f_fwd}, b=F3={b_bck}, n=floor(pi)={n_rep}",
                f"D_A=+{D_A}, D_B={D_B}  =>  D_net={D_net}  (closed loop)",
                f"int_0^1 cos(pi*t_n) dt_n = {integral:.2e}  (= 0 exact)",
                f"f/b = {fib_ratio}  (golden residual phi^2-1)",
                f"CPT-symmetric: {cpt_ok}",
            ],
            'available_equations': [
                "Epoch 5 [9,7,9]: reverse boundary; not predictable from forward physics",
                "SSq drift convergent: [SSq](T)->0.57 with kappa=0.0005 restoring",
                "Wheeler-DeWitt closure: D_net=0 <=> H|Psi>=0",
            ],
            'simulation_set': [
                {'quantity': 'D_net', 'value': D_net},
                {'quantity': 'integral', 'value': integral},
                {'quantity': 'fib_ratio', 'value': fib_ratio},
                {'quantity': 'epochs', 'value': epochs},
                {'quantity': 'cpt_symmetric', 'value': cpt_ok},
            ],
            'source': 'PAPER_1153 Session 203 commit 2637b384',
        }


# -- CP4 #600 -- PAPER_1155 -- DPM 26-Layer Amplification A26 ----------------
class DPMAmplification26LayerCalculator_S234(_CP4Calculator):
    """26-layer DPM amplification: A_26=sum(i^6,i=1..26)=1,307,797,101 exact.
    Nuclear masses: proton/neutron/C-12/Fe-56 within 3% from rho_SCm and [SSq] alone.
    -2.04% residual = E-crack gate correction. PAPER_1155, Session 202 commit 3bfc0a26.
    """
    category = "DPM/Quantum-Chain"
    def compute(self, dataset: dict = None) -> dict:
        d = dataset or {}
        rho = d.get('rho_SCm', float(_SCM_RHO_VAC))
        ssq = d.get('SSq', float(_SCM_SSQ))
        A_26 = sum(i**6 for i in range(1, 27))
        M0 = rho / ssq
        AMU_pred = M0 * A_26
        AMU_obs = 1.661e-27
        error = (AMU_pred - AMU_obs) / AMU_obs * 100
        nuclei = [
            ('Proton', 1, 1.673e-27),
            ('Neutron', 1, 1.675e-27),
            ('C-12', 12, 1.993e-26),
            ('Fe-56', 56, 9.288e-26),
        ]
        nuc_table = []
        for name, A, m_obs in nuclei:
            m_pred = M0 * A_26 * A
            err = (m_pred - m_obs) / m_obs * 100
            nuc_table.append({'name': name, 'A': A, 'm_pred_kg': m_pred,
                               'm_obs_kg': m_obs, 'error_pct': round(err, 2)})
        return {
            'primary_equations': [
                f"w_i = i^6 = [SCm]_i*[UA]_i*B0_i = i^2*i*i^3",
                f"A_26 = sum(i^6, i=1..26) = {A_26}  (exact)",
                f"M0 = rho_SCm/[SSq] = {M0:.4e} kg",
                f"AMU_DPM = M0 * A_26 = {AMU_pred:.4e} kg  (error {error:.2f}%)",
                f"Layer 26 fraction: {26**6/A_26*100:.2f}%",
            ],
            'available_equations': [
                "sum(i^6, 1..N) = N(N+1)(2N+1)(3N^4+6N^3-3N+1)/42",
                "n-p split requires full Ug3 arc-integral (K3=1 placeholder, open)",
                "rho_SCm bootstrap = AMU_obs * [SSq] / A_26 = 7.24e-37 J/m^3",
            ],
            'simulation_set': [
                {'quantity': 'A_26', 'value': A_26},
                {'quantity': 'AMU_derived_kg', 'value': AMU_pred},
                {'quantity': 'error_pct', 'value': error},
                {'quantity': 'nuclear_table', 'value': nuc_table},
            ],
            'source': 'PAPER_1155 Session 202 commit 3bfc0a26',
        }
